DO $$
DECLARE
  q jsonb;
  a jsonb;
BEGIN
  DELETE FROM naesin_templates
  WHERE template_topic = '관계대명사의 계속적 용법'
    AND title LIKE '%Step 3%';

  q := jsonb_build_array(
    jsonb_build_object('number', 1,
  'question', E'[Part 1] 다음 우리말을 영어로 쓸 때, 빈칸에 알맞은 관계대명사를 쓰시오.\n\n(1) 나는 강아지를 한 마리 키우는데, 그것은 아침마다 나를 깨운다.\n→ I have a puppy, __________ wakes me up every morning.\n\n(2) 그는 유명한 소설가인데, 그의 책은 20개국에서 팔렸다.\n→ He is a famous novelist, __________ books have been sold in 20 countries.\n\n(3) 나는 그에게 솔직하게 말했는데, 그것이 결국 우리 관계를 더 좋게 만들었다.\n→ I spoke to him honestly, __________ eventually made our relationship better.\n\n(4) 우리 반에는 친구가 하나 있는데, 그는 다섯 개의 언어를 할 수 있다.\n→ I have a friend in my class, __________ can speak five languages.',
  'subParts', jsonb_build_array(
    jsonb_build_object('label', E'(1)', 'answer', E'which', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(2)', 'answer', E'whose', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(3)', 'answer', E'which', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(4)', 'answer', E'who', 'acceptedAnswers', jsonb_build_array())
  ),
  'answer', E'which / whose / which / who',
  'explanation', E'(1) puppy(사물) 주격 → which (2) 소유격 → whose (3) 앞 문장 전체 → which (4) friend(사람) 주격 → who'),

jsonb_build_object('number', 2,
  'question', E'다음 주어진 정보를 이용하여 보기와 같이 문장을 완성하시오.\n\n[보기] Mona Lisa — It was painted by Leonardo da Vinci.\n→ This is the Mona Lisa, which was painted by Leonardo da Vinci.\n\n• Bulguksa Temple — It was built during the Silla Dynasty.\n• Albert Einstein — He developed the theory of relativity.\n• The Amazon River — It is the longest river in South America.\n\n(1) This is Bulguksa Temple, _________________________________________.\n(2) This is Albert Einstein, __________________________________________.\n(3) This is the Amazon River, _________________________________________.',
  'subParts', jsonb_build_array(
    jsonb_build_object('label', E'(1)', 'answer', E'which was built during the Silla Dynasty', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(2)', 'answer', E'who developed the theory of relativity', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(3)', 'answer', E'which is the longest river in South America', 'acceptedAnswers', jsonb_build_array())
  ),
  'answer', E'which was built during the Silla Dynasty / who developed the theory of relativity / which is the longest river in South America',
  'explanation', E'(1) Bulguksa Temple(사물) → which (2) Albert Einstein(사람) → who (3) The Amazon River(사물) → which'),

jsonb_build_object('number', 3,
  'question', E'다음 사람들의 계획을 보고 보기와 같이 문장을 완성하시오.\n\n[보기] Junho — going to see his dentist / She is very gentle and skillful.\n→ Junho is going to see his dentist, who is very gentle and skillful.\n\nSoyeon — planning to read Demian / It is her favorite novel of all time.\nTaeyang — going to visit his grandfather / He lives alone in a small village.\nNaeun — planning to join a cooking class / It opened just last week.\n\n(1) Soyeon → ___________________________________________________\n(2) Taeyang → __________________________________________________\n(3) Naeun → ____________________________________________________',
  'subParts', jsonb_build_array(
    jsonb_build_object('label', E'(1)', 'answer', E'Soyeon is planning to read Demian, which is her favorite novel of all time.', 'acceptedAnswers', jsonb_build_array(E'Soyeon is planning to read Demian, which is her favorite novel of all time')),
    jsonb_build_object('label', E'(2)', 'answer', E'Taeyang is going to visit his grandfather, who lives alone in a small village.', 'acceptedAnswers', jsonb_build_array(E'Taeyang is going to visit his grandfather, who lives alone in a small village')),
    jsonb_build_object('label', E'(3)', 'answer', E'Naeun is planning to join a cooking class, which opened just last week.', 'acceptedAnswers', jsonb_build_array(E'Naeun is planning to join a cooking class, which opened just last week'))
  ),
  'answer', E'Soyeon is planning to read Demian, which is her favorite novel of all time. / Taeyang is going to visit his grandfather, who lives alone in a small village. / Naeun is planning to join a cooking class, which opened just last week.',
  'explanation', E'(1) Demian(사물) → which (2) grandfather(사람) → who (3) cooking class(사물) → which'),

jsonb_build_object('number', 4,
  'question', E'다음 두 문장이 같은 의미가 되도록 빈칸에 알맞은 관계대명사를 쓰시오.\n\n(1) She returned all the money she owed, and it impressed everyone.\n→ She returned all the money she owed, __________ impressed everyone.\n\n(2) We all like Coach Bae, for he always puts the team first.\n→ We all like Coach Bae, __________ always puts the team first.\n\n(3) I went to the new gallery, but it was closed for a private event.\n→ I went to the new gallery, __________ was closed for a private event.\n\n(4) She has two daughters, and they are both studying architecture.\n→ She has two daughters, __________ are both studying architecture.',
  'subParts', jsonb_build_array(
    jsonb_build_object('label', E'(1)', 'answer', E'which', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(2)', 'answer', E'who', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(3)', 'answer', E'which', 'acceptedAnswers', jsonb_build_array()),
    jsonb_build_object('label', E'(4)', 'answer', E'who', 'acceptedAnswers', jsonb_build_array())
  ),
  'answer', E'which / who / which / who',
  'explanation', E'(1) and it → which (2) for he → who (3) but it → which (4) and they → who'),

jsonb_build_object('number', 5,
  'question', E'다음 분실물 보관소의 물건들을 보고, 관계대명사를 사용하여 문장을 완성하시오.\n\n[보기] bag — left on the train on April 3rd\n→ I lost my bag, which I left on the train on April 3rd.\n\n• water bottle — found near the school entrance\n• gray hoodie — covered in paint stains\n• laptop — made in Germany\n\n(1) I''m looking for my water bottle, ___________________________________.\n(2) I lost my gray hoodie, ____________________________________________.\n(3) I''m trying to find my laptop, _______________________________________.',
  'subParts', jsonb_build_array(
