    jsonb_build_object('label', E'(3)', 'answer', E'which was made in Germany', 'acceptedAnswers', jsonb_build_array(E'which is made in Germany'))
  ),
  'answer', E'which was found near the school entrance / which was covered in paint stains / which was made in Germany',
  'explanation', E'모두 사물 선행사 → which'),

jsonb_build_object('number', 6,
  'question', E'다음 which의 선행사를 각각 쓰시오.\n\n(1) She forgot to set her alarm, which made her miss the first class.\n→ 선행사: ___________________________\n\n(2) I visited the old library, which had recently been restored.\n→ 선행사: ___________________________\n\n(3) He said he had finished the report, which was not true at all.\n→ 선행사: ___________________________',
